shader_type canvas_item;

uniform float grow : hint_range(0.1, 2.0) = 1.0;

void vertex() {
	mat2 scale_table = mat2(vec2(grow, 0.0), vec2(0.0, grow));
	VERTEX = scale_table * VERTEX;
}

shader_type canvas_item;

uniform float angle : hint_range(0.0, 6.2832) = 0.0;

void vertex() {
	vec2 across = vec2(cos(angle), sin(angle));
	vec2 down = vec2(-sin(angle), cos(angle));
	VERTEX = mat2(across, down) * VERTEX;
}

shader_type canvas_item;

uniform vec2 slide = vec2(100.0, 0.0);

void vertex() {
	vec3 across = vec3(1.0, 0.0, 0.0);
	vec3 down = vec3(0.0, 1.0, 0.0);
	vec3 offset = vec3(slide, 1.0);
	VERTEX = (mat3(across, down, offset) * vec3(VERTEX, 1.0)).xy;
}
